// Edit the email subject/body in the TEXTOS section below (default language: Spanish).
const cfg = $('Set business settings').first().json;

// ===== Utilidades (no hace falta tocarlas) =====
const ZONA = cfg.zona_horaria || 'Europe/Madrid';
const si = v => /^(s[ií]|si|yes|true|1|x|ok)$/i.test(String(v ?? '').trim());
function normTel(t) {
  let s = String(t ?? '').replace(/[^\d+]/g, '');
  if (!s) return '';
  if (s.startsWith('00')) s = '+' + s.slice(2);
  if (!s.startsWith('+')) s = (s.length === 9 ? '+34' : '+') + s;
  return s;
}
function parseCita(r) {
  const f = String(r.fecha ?? '').trim();
  const h = String(r.hora ?? '').trim();
  let y, m, d, mm;
  if ((mm = f.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/))) { y = +mm[1]; m = +mm[2]; d = +mm[3]; }
  else if ((mm = f.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})$/))) { d = +mm[1]; m = +mm[2]; y = +mm[3]; if (y < 100) y += 2000; }
  else if (/^\d+(\.\d+)?$/.test(f)) { const b = DateTime.fromObject({ year: 1899, month: 12, day: 30 }, { zone: ZONA }).plus({ days: Math.floor(+f) }); y = b.year; m = b.month; d = b.day; }
  else return null;
  const hm = h.match(/^(\d{1,2})[:.h](\d{2})/) || [null, '0', '0'];
  const dt = DateTime.fromObject({ year: y, month: m, day: d, hour: +hm[1], minute: +hm[2] }, { zone: ZONA });
  return dt.isValid ? dt : null;
}
const estadoDe = r => String(r.estado || 'pendiente').toLowerCase().trim().replace('ó', 'o').replace(/\s+/g, '_');
const nombreCorto = n => String(n || '').trim().split(/\s+/)[0] || '';
const fechaTexto = dt => dt.setLocale('es').toFormat("cccc d 'de' LLLL");
const precioNum = p => { const n = parseFloat(String(p ?? '').replace(/[^\d,.-]/g, '').replace(',', '.')); return isNaN(n) ? 0 : n; };
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
function plantillaEmail(titulo, parrafos, boton) {
  const btn = boton ? `<p style="margin:24px 0"><a href="${esc(boton.url)}" style="background:#111;color:#fff;padding:12px 20px;border-radius:8px;text-decoration:none;font-weight:bold">${esc(boton.texto)}</a></p>` : '';
  return `<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:auto;color:#222;line-height:1.5">
<h2 style="margin-bottom:8px">${esc(titulo)}</h2>${parrafos.map(p => `<p>${p}</p>`).join('')}${btn}
<p style="color:#777;font-size:13px;border-top:1px solid #eee;padding-top:12px">${esc(cfg.nombre_negocio)} · ${esc(cfg.direccion)} · ${esc(cfg.telefono_negocio)}</p></div>`;
}
// ===== Fin utilidades =====


const ahora = DateTime.now().setZone(ZONA);
const horas = Number(cfg.horas_antelacion) || 24;
const limite = ahora.plus({ hours: horas });
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  if (!r.id) continue;
  if (['cancelada', 'completada', 'no_asistio'].includes(estadoDe(r))) continue;
  if (String(r.recordatorio_enviado ?? '').trim()) continue;
  const dt = parseCita(r);
  if (!dt || dt <= ahora || dt > limite) continue;
  const tel = normTel(r.telefono);
  const email = String(r.email ?? '').trim();
  let canal = null;
  if (email.includes('@')) canal = 'email';
  if (!canal) continue;
  const c = { id: String(r.id), cliente: String(r.cliente ?? ''), nombre: nombreCorto(r.cliente) || 'hola', telefono_wa: tel.replace('+', ''),
    email, servicio: String(r.servicio || 'tu cita'), profesional: String(r.profesional ?? ''), fecha_texto: fechaTexto(dt), hora_texto: dt.toFormat('HH:mm'), canal };
  // ===== TEXTOS =====
  c.asunto = `Recordatorio: tu cita en ${cfg.nombre_negocio} el ${c.fecha_texto} a las ${c.hora_texto}`;
  c.html = plantillaEmail(`¡Hola ${c.nombre}!`, [
    `Te recordamos tu cita de <b>${esc(c.servicio)}</b>${c.profesional ? ' con ' + esc(c.profesional) : ''} el <b>${esc(c.fecha_texto)} a las ${c.hora_texto}</b>.`,
    `Si no puedes venir, avísanos cuanto antes respondiendo a este email o llamando al ${esc(cfg.telefono_negocio)}: así otra persona puede aprovechar el hueco.`,
    `<a href="${esc(cfg.link_maps)}">Cómo llegar</a>`], { texto: 'Cambiar o cancelar mi cita', url: cfg.link_reservas });
  // ==================
  out.push({ json: c });
}
return out;
